from common import add, case
# Niveau 1 : syntaxe, expressions et collections sans pièges de durée de vie.
add(1,'variables','mutable_binding',lambda n:case(f'let mut x={n};x+=3;print!("{{}}",x);',n+3,'mut autorise la réaffectation de la liaison ; aucune référence mutable n’est nécessaire pour cette variable locale.','La liaison x est mutable|x est un entier signé inféré|+= modifie la variable existante','mut alloue sur le tas|x doit être une référence|La modification exige unsafe'))
add(1,'variables','shadowing_type',lambda n:case(f'let x="abc{n}";let x=x.len();print!("{{}}",x);',4,'Une nouvelle liaison peut masquer la précédente et changer de type. len renvoie ici un usize.','Le deuxième let crée une nouvelle liaison|Le deuxième x a le type usize|Le premier x est une tranche de chaîne','Le deuxième let modifie le type de l’ancien objet|Shadowing exige mut|len renvoie un i32'))
add(1,'functions','tail_expression',lambda n:case(f'print!("{{}}",inc({n}));',n+1,'La dernière expression sans point-virgule fournit la valeur de retour.','Le corps renvoie x+1|Le type de retour est i32|Le mot return est facultatif ici','La dernière expression doit finir par un point-virgule|La fonction renvoie ()|L’appel déplace obligatoirement une allocation',preamble='fn inc(x:i32)->i32{x+1}'))
add(1,'control_flow','if_expression',lambda n:case(f'let x=if {n}%2==0{{10}}else{{20}};print!("{{}}",x);',10 if n%2==0 else 20,'if est une expression ; les branches utilisées pour produire x ont des types compatibles.','if produit une valeur|Les deux branches ont ici le même type|Une seule branche est exécutée','if ne peut pas initialiser une variable|Les deux branches sont exécutées|Les accolades sont facultatives en Rust'))
add(1,'loops','exclusive_range',lambda n:case(f'let s:i32=(0..{n+3}).sum();print!("{{}}",s);',sum(range(n+3)),'La borne supérieure de a..b est exclue. sum additionne les éléments de l’itérateur.','La borne haute est exclue|sum consomme l’itérateur|Le type de s est explicite','La plage inclut systématiquement sa fin|sum renvoie toujours usize|La plage modifie une variable externe'))
add(1,'loops','inclusive_range',lambda n:case(f'let s:i32=(1..={n+3}).sum();print!("{{}}",s);',sum(range(1,n+4)),'..= inclut la borne supérieure, contrairement à a..b.','La borne supérieure est incluse|La somme est calculée sans boucle explicite|La plage est finie','La borne supérieure est exclue|sum retourne un Vec|La plage nécessite unsafe'))
add(1,'arrays','array_repeat',lambda n:case(f'let a=[{n};4];print!("{{}} {{}}",a.len(),a[3]);',f'4 {n}','[valeur; longueur] initialise un tableau de longueur fixe ; les petits entiers implémentent Copy.','La longueur est fixée dans le type|Tous les éléments ont la même valeur initiale|L’indice trois est valide','a est un Vec|La longueur vaut la valeur répétée|L’indice quatre est le dernier valide',wrong=[f'{n} 4',f'4 {n+1}','Erreur de compilation']))
add(1,'collections','vec_push',lambda n:case(f'let mut v=vec![{n},2];v.push(9);print!("{{}} {{}}",v.len(),v[2]);','3 9','push ajoute un élément et peut agrandir la capacité. len compte les éléments initialisés.','v doit être mutable pour push|len compte les éléments|Le troisième élément est accessible à l’indice deux','La capacité vaut forcément trois|push renvoie un nouveau Vec|Vec impose une taille fixe',wrong=['2 9','3 2','Erreur de compilation']))
add(1,'strings','utf8_length',lambda n:case(f'let s="é{n}";print!("{{}} {{}}",s.len(),s.chars().count());','3 2','len compte les octets UTF-8 ; chars compte les valeurs scalaires Unicode. é utilise deux octets.','len compte des octets|chars itère sur les valeurs scalaires|La chaîne est du UTF-8 valide','len compte des graphèmes|Chaque caractère utilise un octet|chars retourne des indices d’octets',wrong=['2 2','3 3','2 3']))
add(1,'ownership','copy_integer',lambda n:case(f'let a={n};let b=a;print!("{{}} {{}}",a,b);',f'{n} {n}','i32 implémente Copy ; l’affectation laisse a utilisable.','Les entiers i32 sont Copy|a reste utilisable après l’affectation|Aucune allocation String n’intervient','L’affectation déplace une String|a devient inaccessible|Un clone explicite est obligatoire',wrong=['Erreur de compilation',f'{n} 0','Panic garanti']))
add(1,'ownership','string_move',lambda n:case(f'let a=String::from("mot{n}");let b=a;print!("{{}}",a);','Erreur de compilation','String n’est pas Copy ; a est déplacée dans b et ne peut plus être utilisée.','b reçoit la propriété|a n’est plus utilisable|clone créerait une copie indépendante','L’affectation clone automatiquement|Le code provoque un panic à l’exécution|String implémente Copy',mode='compile_fail'))
add(1,'borrowing','immutable_borrow',lambda n:case(f'let s=String::from("abc{n}");let r=&s;print!("{{}} {{}}",r.len(),s.len());','4 4','Un emprunt partagé ne déplace pas la String et permet plusieurs lectures.','r est une référence partagée|s reste propriétaire|Les lectures peuvent coexister','&s déplace la String|Toute référence exige mut|Deux lectures simultanées sont interdites',wrong=['Erreur de compilation','4 0','Panic garanti']))
add(1,'enum','option_match',lambda n:case(f'let x=Some({n});let y=match x{{Some(v)=>v+2,None=>0}};print!("{{}}",y);',n+2,'match choisit le bras correspondant et extrait la valeur de Some.','Some contient une valeur|Le match couvre Some et None|Le résultat des bras est un entier','None contient un zéro implicite|Tous les bras sont exécutés|Option est un pointeur brut'))
add(1,'enum','result_default',lambda n:case(f'let r:Result<i32,&str>=Err("absent");print!("{{}}",r.unwrap_or({n+4}));',n+4,'unwrap_or fournit la valeur de secours sur Err, sans panic.','r contient une erreur|La valeur de secours est un i32|unwrap_or traite Err sans panic','Err est identique à None au niveau du type|unwrap_or panique sur Err|Le message d’erreur est affiché automatiquement'))
add(1,'control_flow','match_exhaustive',lambda n:case(f'let x=Some({n});match x{{Some(v)=>print!("{{}}",v)}}','Erreur de compilation','Un match sur Option doit aussi couvrir None, même si la valeur locale vient de Some.','Le cas None manque|L’exhaustivité est vérifiée à la compilation|Un bras générique _ pourrait couvrir les cas restants','Le compilateur ignore None si x vaut Some|Le code panique seulement si None arrive|Option ne peut être utilisé avec match',mode='compile_fail'))
add(1,'structures','struct_update',lambda n:case(f'let a=P{{x:{n},y:8}};let b=P{{x:5,..a}};print!("{{}} {{}}",b.x,b.y);','5 8','La syntaxe de mise à jour reprend les champs omis. Ici les champs sont des i32 Copy.','x est remplacé explicitement|y est repris de a|Les champs de ce type sont Copy','Tous les champs sont mis à zéro|La syntaxe crée une référence vers a|Le champ y doit être réécrit',preamble='struct P{x:i32,y:i32}',wrong=[f'{n} 8','5 0','Erreur de compilation']))
add(1,'collections','get_option',lambda n:case(f'let v=vec![{n},2];print!("{{}}",v.get(9).is_none());','true','get fournit Option<&T> et retourne None si l’indice n’existe pas.','get ne panique pas pour cet indice|Le retour est une Option|La collection n’est pas agrandie','get renvoie une référence invalide|L’accès ajoute des éléments|Le code ne compile pas',wrong=['false','Panic','Erreur de compilation']))
add(1,'functions','tuple_destructure',lambda n:case(f'let (a,_,c)=({n},7,9);print!("{{}}",a+c);',n+9,'La déstructuration extrait les premier et troisième éléments ; _ ignore le second.','Le tuple contient trois éléments|_ ignore un élément|Les liaisons a et c sont distinctes','_ devient une variable utilisable|Tous les éléments doivent avoir des types différents|Un tuple ne peut pas être déstructuré'))
add(1,'collections','iterator_map',lambda n:case(f'let v:Vec<i32>=(1..={n+2}).map(|x|x*2).collect();print!("{{}}",v[0]);',2,'map transforme paresseusement chaque élément ; collect matérialise le résultat.','map est paresseux|collect construit un Vec|L’ordre de la plage est conservé','map modifie obligatoirement la plage|collect trie le résultat|Le premier élément de la plage est zéro'))
add(1,'loops','break_value',lambda n:case(f'let x=loop{{break {n+7};}};print!("{{}}",x);',n+7,'Une boucle loop peut produire la valeur fournie à break.','loop est une expression|break fournit la valeur|Le corps s’exécute une fois ici','break ne peut jamais porter de valeur|loop impose une boucle infinie|Le résultat est nécessairement ()'))

# Niveau 2 : déplacements, itérateurs, erreurs et outils de bibliothèque.
add(2,'borrowing','nll_last_use',lambda n:case(f'let mut x={n};let r=&x;let a=*r;let m=&mut x;*m+=2;print!("{{}} {{}}",a,x);',f'{n} {n+2}','L’emprunt partagé n’est plus utilisé au moment de l’emprunt mutable ; les durées de vie non lexicales le permettent.','Le dernier usage de r précède m|m permet une écriture exclusive|a contient une copie de l’entier','r bloque toujours jusqu’à la fin du bloc|Une référence partagée modifie x|Le code requiert unsafe',wrong=['Erreur de compilation',f'{n+2} {n+2}','Panic garanti']))
add(2,'borrowing','two_mutable_borrows',lambda n:case(f'let mut x={n};let a=&mut x;let b=&mut x;print!("{{}} {{}}",a,b);','Erreur de compilation','Deux emprunts mutables du même objet ne peuvent pas rester actifs et être utilisés simultanément.','Les deux références visent x|a est encore utilisé après la création de b|La vérification est statique','Les emprunts sont automatiquement clonés|Le code compile puis panique|Ajouter mut à a résout le conflit',mode='compile_fail'))
add(2,'ownership','clone_string',lambda n:case(f'let a=String::from("ab{n}");let mut b=a.clone();b.push(\'!\');print!("{{}} {{}}",a.len(),b.len());','3 4','clone duplique le contenu de la String. Modifier b ne modifie pas a.','Les deux String possèdent leur stockage|a reste utilisable|push modifie seulement b','clone crée uniquement un alias mutable|String devient Copy après clone|Le contenu de a change avec b',wrong=['4 4','Erreur de compilation','3 3']))
add(2,'strings','utf8_boundary',lambda n:case(f'let s="é{n}";print!("{{}}",&s[0..1]);','Panic à l’exécution','L’octet 1 coupe l’encodage UTF-8 de é. Une tranche str doit commencer et finir sur des frontières de caractères.','La plage est dans le nombre total d’octets|La frontière de fin est invalide|Le contrôle provoque un panic en code sûr','Le compilateur interdit toute tranche de str|La sortie est forcément é|Le programme a un comportement indéfini',wrong=['é','Erreur de compilation','Comportement indéfini'],mode='panic'))
add(2,'enum','question_mark',lambda n:case(f'print!("{{}}",parse("{n+9}").unwrap());',n+10,'? propage une erreur compatible vers l’appelant ou extrait la valeur sur Ok.','La fonction retourne Result|? propage une erreur de parse|Le chemin de succès ajoute un','? déclenche toujours un panic|? transforme Err en None|La fonction doit retourner un bool',preamble='fn parse(s:&str)->Result<i32,std::num::ParseIntError>{let x=s.parse::<i32>()?;Ok(x+1)}'))
add(2,'collections','hashmap_entry',lambda n:case(f'let mut m=std::collections::HashMap::new();*m.entry("a").or_insert({n})+=2;print!("{{}}",m["a"]);',n+2,'entry permet d’obtenir ou d’insérer la valeur ; or_insert renvoie une référence mutable sur la valeur stockée.','La clé est absente au départ|or_insert fournit une référence mutable|La mise à jour agit dans la map','or_insert renvoie une copie indépendante|entry trie les clés|L’indexation insère une clé absente'))
add(2,'collections','iterator_laziness',lambda n:case(f'let mut count=0;{{let _it=(0..{n+2}).map(|x|{{count+=1;x}});}}print!("{{}}",count);',0,'Créer un map ne consomme pas l’itérateur. La fermeture n’est donc jamais appelée.','L’itérateur n’est jamais consommé|La fermeture pourrait modifier count|L’emprunt de count prend fin avant print','Créer map parcourt immédiatement la plage|Le nom _it consomme chaque élément|La fermeture s’exécute au moins une fois'))
add(2,'collections','filter_map_parse',lambda n:case(f'let s=["{n}","x","{n+2}"];let v:Vec<i32>=s.iter().filter_map(|x|x.parse().ok()).collect();print!("{{}}",v.len());',2,'filter_map conserve les Some et ignore les None ; ok transforme les échecs de parse en None.','La chaîne x est ignorée|L’ordre des nombres est conservé|La sortie possède des i32','L’échec de parse panique|Le résultat contient trois nombres|filter_map exige que toutes les conversions réussissent'))
add(2,'ownership','iter_vs_into_iter',lambda n:case(f'let v=vec![String::from("a{n}")];let len=v.iter().next().unwrap().len();print!("{{}} {{}}",v.len(),len);','1 2','iter emprunte les éléments ; il ne consomme pas le Vec et ne déplace pas les String.','iter fournit des références|v reste utilisable|La String n’est pas déplacée','iter consomme le Vec|next clone automatiquement la String|Le code impose que String soit Copy',wrong=['Erreur de compilation','0 2','1 0']))
add(2,'ownership','move_closure_copy',lambda n:case(f'let x={n};let f=move||x+1;print!("{{}} {{}}",x,f());',f'{n} {n+1}','move capture x par valeur, mais i32 est Copy : la liaison extérieure reste utilisable.','La fermeture capture par valeur|i32 implémente Copy|La fermeture peut être appelée sans mut','move rend toujours la variable extérieure inutilisable|La fermeture emprunte x mutuellement|Tout move alloue sur le tas',wrong=['Erreur de compilation',f'{n+1} {n+1}','Panic garanti']))
add(2,'enum','option_take',lambda n:case(f'let mut x=Some(String::from("a{n}"));let y=x.take();print!("{{}} {{}}",x.is_none(),y.is_some());','true true','take remplace l’Option par None et renvoie sa valeur précédente, sans cloner la String.','La String est déplacée vers y|x reste une Option valide|x contient None après take','take clone la String|x devient une variable déplacée inutilisable|y contient obligatoirement None',wrong=['false true','Erreur de compilation','true false']))
add(2,'enum','unwrap_or_else_lazy',lambda n:case(f'let mut calls=0;let x=Some({n}).unwrap_or_else(||{{calls+=1;9}});print!("{{}} {{}}",x,calls);',f'{n} 0','La fermeture de secours n’est exécutée que sur None.','Le chemin Some est pris|La fermeture n’est pas exécutée|unwrap_or_else est paresseux pour le secours','La fermeture est toujours exécutée|Le secours remplace Some|La fermeture doit être move',wrong=[f'{n} 1','9 1','Erreur de compilation']))
add(2,'structures','borrow_self_method',lambda n:case(f'let mut c=Counter({n});c.inc();print!("{{}}",c.0);',n+1,'Un récepteur &mut self emprunte mutuellement l’objet sans en prendre la propriété.','La liaison c est mutable|La méthode emprunte c|c reste utilisable après l’appel','La méthode consomme c|&mut self clone l’objet|La méthode exige unsafe',preamble='struct Counter(i32);impl Counter{fn inc(&mut self){self.0+=1;}}'))
add(2,'generics','generic_copy_bound',lambda n:case(f'let x=String::from("x{n}");let _=duplicate(x);','Erreur de compilation','La borne Copy n’est pas satisfaite par String. Une borne Clone avec un appel explicite à clone aurait un autre contrat.','La fonction impose Copy|String n’est pas Copy|La vérification est à la compilation','Tout type Clone est Copy|Les bornes sont ignorées après monomorphisation|La String est automatiquement clonée',preamble='fn duplicate<T:Copy>(x:T)->(T,T){(x,x)}',mode='compile_fail'))
add(2,'enum','if_let_binding',lambda n:case(f'let x=Some({n});let mut s=0;if let Some(v)=x{{s=v+2;}}print!("{{}}",s);',n+2,'if let exécute le corps uniquement si le motif correspond ; l’entier extrait est Copy.','Le motif correspond|v est disponible dans le corps|Le cas None est simplement ignoré','if let exige un else|Le corps s’exécute sur None|v reste en portée après le bloc'))
add(2,'collections','retain_even',lambda n:case(f'let mut v:Vec<i32>=(0..={n+3}).collect();v.retain(|x|x%2==0);print!("{{}}",v.len());',len([x for x in range(n+4) if x%2==0]),'retain conserve les éléments satisfaisant le prédicat, sans changer l’ordre relatif.','Les éléments pairs sont conservés|Le Vec est modifié en place|L’ordre relatif est préservé','retain crée obligatoirement un nouveau Vec|Les éléments impairs sont conservés|La capacité est forcément égale à len après retain'))
add(2,'ownership','box_deref',lambda n:case(f'let mut b=Box::new({n});*b+=4;print!("{{}}",*b);',n+4,'Box possède une allocation ; son déréférencement permet ici de modifier l’entier via une liaison mutable.','Box possède l’entier alloué|La valeur est libérée à la destruction|Le déréférencement est sûr ici','Box fournit automatiquement plusieurs propriétaires|free est obligatoire|Le déréférencement nécessite unsafe'))
add(2,'collections','zip_shortest',lambda n:case(f'let a=[{n},2,3];let b=[4,5];print!("{{}}",a.iter().zip(b.iter()).count());',2,'zip s’arrête dès qu’un des deux itérateurs n’a plus d’élément.','Le second tableau est plus court|zip produit des couples|count consomme l’itérateur','zip complète avec des zéros|Le nombre de couples vaut la somme des longueurs|zip modifie les tableaux'))
add(2,'strings','string_push_char',lambda n:case(f'let mut s=String::from("a{n}");s.push(\'é\');print!("{{}} {{}}",s.len(),s.chars().count());','4 3','push ajoute un char encodé en UTF-8 ; é ajoute deux octets mais une seule valeur scalaire.','push accepte un char|La chaîne reste du UTF-8 valide|La longueur en octets diffère du nombre de chars','push ajoute toujours un octet|String stocke un char par case fixe|La capacité vaut forcément len',wrong=['3 3','4 4','Erreur de compilation']))
add(2,'variables','checked_add',lambda n:case(f'let x=u8::MAX;print!("{{}}",x.checked_add({n}).is_none());','true','checked_add représente le débordement par None, indépendamment du mode debug ou release.','Le débordement est signalé par None|Le résultat est une Option|La sémantique ne dépend pas des vérifications de débordement usuelles','L’opération panique toujours|Elle boucle automatiquement modulo 256|Elle renvoie un Result',wrong=['false','Panic garanti','Erreur de compilation']))

# Niveau 3 : durées de vie, traits, alias contrôlés et concurrence.
add(3,'lifetimes','return_local_reference',lambda n:case('let _r=bad();','Erreur de compilation','Aucune annotation ne peut prolonger la durée de vie d’une String locale détruite au retour.','s est local à bad|Le retour prétend fournir une référence statique|Retourner une String possédée éviterait cette référence pendante','Écrire static allonge la vie de s|Le code compile et donne une référence pendante|Box est la seule correction possible',preamble=f'fn bad()->&\'static str{{let s=String::from("x{n}");&s}}',mode='compile_fail'))
add(3,'borrowing','split_at_mut',lambda n:case(f'let mut a=[{n},2,3,4];let (l,r)=a.split_at_mut(2);l[0]+=1;r[0]+=2;print!("{{}} {{}}",a[0],a[2]);',f'{n+1} 5','split_at_mut expose deux tranches mutables disjointes ; l’API sûre garantit l’absence de recouvrement.','Les tranches sont disjointes|Les deux emprunts mutables coexistent légalement|Les écritures visent deux éléments différents','Deux tranches mutables sont toujours interdites|Le tableau est cloné|L’appel nécessite unsafe',wrong=['Erreur de compilation',f'{n} 3','Panic garanti']))
add(3,'ownership','rc_counts',lambda n:case(f'let a=std::rc::Rc::new({n});let b=a.clone();drop(b);print!("{{}}",std::rc::Rc::strong_count(&a));',1,'Cloner Rc ajoute un propriétaire du même objet ; drop(b) retire sa référence forte.','clone partage l’allocation|Le compteur est décrémenté par drop|Rc ne fournit pas de sécurité de partage entre threads','clone recopie l’entier dans une nouvelle allocation|Rc est toujours Send|drop(b) rend a invalide'))
add(3,'borrowing','refcell_runtime_check',lambda n:case(f'let c=std::cell::RefCell::new({n});let a=c.borrow_mut();let b=c.borrow();print!("{{}} {{}}",a,b);','Panic à l’exécution','RefCell vérifie les emprunts à l’exécution : un emprunt partagé est refusé pendant un emprunt mutable actif.','Le premier emprunt est exclusif|Le second emprunt est vérifié à l’exécution|Le code peut compiler en Rust sûr','RefCell désactive toutes les règles d’emprunt|Le compilateur refuse nécessairement ce code|Les deux emprunts accèdent à des copies',wrong=['Erreur de compilation','Comportement indéfini garanti',str(n)],mode='panic'))
add(3,'concurrency','arc_mutex',lambda n:case(f'let x=std::sync::Arc::new(std::sync::Mutex::new({n}));let y=x.clone();let h=std::thread::spawn(move||{{*y.lock().unwrap()+=2;}});h.join().unwrap();print!("{{}}",*x.lock().unwrap());',n+2,'Arc partage la propriété entre threads ; Mutex protège la mutation, et join attend la fin du thread.','Arc est cloné pour le thread|Mutex protège l’accès mutable|join garantit que le thread est terminé','Arc rend seul toute mutation sûre|Mutex clone la valeur protégée|Le thread peut encore modifier x après le join réussi'))
add(3,'generics','trait_object_dispatch',lambda n:case(f'let x=Number({n});let r:&dyn Value=&x;print!("{{}}",r.value());',n+1,'&dyn Value utilise un objet de trait et une répartition dynamique ; la méthode n’a pas de paramètre de type générique.','Le trait est utilisable comme objet ici|La référence ne déplace pas x|L’appel passe par une interface dynamique','dyn impose que Number soit Copy|Le trait est transformé en enum|La méthode doit obligatoirement être statique',preamble='trait Value{fn value(&self)->i32;}struct Number(i32);impl Value for Number{fn value(&self)->i32{self.0+1}}'))
add(3,'lifetimes','longest_borrow',lambda n:case(f'let outer=String::from("long{n}");let r;{{let inner=String::from("x");r=longer(&outer,&inner);}}print!("{{}}",r);','Erreur de compilation','La signature lie le retour aux deux arguments ; le compilateur ne déduit pas que cette exécution renverra toujours outer.','Le retour est lié à la durée commune|inner est détruit avant print|Une comparaison des longueurs à l’exécution ne change pas le contrat statique','Le compilateur prouve que outer est toujours plus longue|L’annotation prolonge inner|Le code provoque seulement un panic',preamble="fn longer<'a>(a:&'a str,b:&'a str)->&'a str{if a.len()>b.len(){a}else{b}}",mode='compile_fail'))
add(3,'ownership','drop_order',lambda n:case(f'let _a=Log({n});{{let _b=Log({n+1});}}print!("x");',f'{n+1}x{n}','Les variables locales sont détruites à la fin de leur portée, en ordre inverse de déclaration dans une même portée.','_b est détruit avant le print|_a reste vivant pendant le bloc interne|Le préfixe souligné n’empêche pas le destructeur','_a est détruit au premier usage|_b est oublié sans drop|L’ordre est choisi aléatoirement',preamble='struct Log(i32);impl Drop for Log{fn drop(&mut self){print!("{}",self.0);}}',wrong=[f'x{n+1}{n}',f'{n}x{n+1}','Erreur de compilation']))
add(3,'ownership','fn_once_capture',lambda n:case(f'let s=String::from("v{n}");let f=move||s;let _a=f();let _b=f();','Erreur de compilation','La fermeture sort sa String capturée au premier appel ; elle n’implémente que FnOnce et ne peut pas être rappelée.','La capture est possédée|Le premier appel déplace s hors de la fermeture|La fermeture est consommée par cet appel','Toute fermeture move est réutilisable|Ajouter mut à f recrée s|La String est clonée à chaque appel',mode='compile_fail'))
add(3,'generics','associated_type',lambda n:case(f'let mut c=Count({n});print!("{{}}",c.next().unwrap());',n+1,'Iterator associe un type Item à l’implémentation ; next renvoie Option<Self::Item>.','Item est ici i32|next emprunte mutuellement self|Some contient la nouvelle valeur','Item est choisi de nouveau à chaque appel|next consomme obligatoirement c|Un trait ne peut pas avoir de type associé',preamble='struct Count(i32);impl Iterator for Count{type Item=i32;fn next(&mut self)->Option<i32>{self.0+=1;Some(self.0)}}'))
add(3,'collections','drain_drop',lambda n:case(f'let mut v=vec![{n},2,3,4];{{let mut d=v.drain(1..3);let _=d.next();}}print!("{{}}",v.len());',2,'La destruction de Drain termine le retrait de la plage demandée, y compris les éléments non encore produits.','La plage retire les indices un et deux|Le Drain emprunte le Vec|Le Vec reste utilisable après destruction du Drain','Seul l’élément obtenu par next est retiré|Le Vec est entièrement vidé|drain clone la plage'))
add(3,'concurrency','atomic_relaxed',lambda n:case(f'let x=std::sync::atomic::AtomicUsize::new({n});let a=x.fetch_add(2,std::sync::atomic::Ordering::Relaxed);print!("{{}} {{}}",a,x.load(std::sync::atomic::Ordering::Relaxed));',f'{n} {n+2}','fetch_add est atomique et renvoie l’ancienne valeur. Relaxed ne publie pas à lui seul des écritures vers d’autres objets.','L’addition est atomique|La valeur retournée est l’ancienne|Relaxed n’établit pas à lui seul une synchronisation inter-objets','Relaxed rend l’opération non atomique|fetch_add retourne toujours la nouvelle valeur|Relaxed équivaut toujours à SeqCst',wrong=[f'{n+2} {n+2}',f'{n} {n}','Erreur de compilation']))
add(3,'borrowing','cell_copy',lambda n:case(f'let c=std::cell::Cell::new({n});let r=&c;r.set(r.get()+3);print!("{{}}",c.get());',n+3,'Cell fournit une mutabilité intérieure sûre pour des opérations par copie ; aucune référence intérieure n’est exposée.','La référence r peut être partagée|get copie ici un i32|set remplace la valeur intérieure','Une référence partagée interdit toute mutabilité intérieure|Cell fournit un &mut i32 au demandeur|get fonctionne par copie pour toute String'))
add(3,'ownership','weak_upgrade',lambda n:case(f'let weak;{{let a=std::rc::Rc::new({n});weak=std::rc::Rc::downgrade(&a);}}print!("{{}}",weak.upgrade().is_none());','true','Weak n’empêche pas la destruction de la valeur lorsque le dernier Rc fort disparaît ; upgrade retourne alors None.','Weak ne maintient pas la valeur en vie|Le dernier propriétaire fort sort de portée|upgrade peut échouer sans panic','Weak compte comme un propriétaire fort|upgrade recrée obligatoirement l’ancienne valeur|La référence faible provoque un use-after-free en code sûr',wrong=['false','Erreur de compilation','Comportement indéfini']))
add(3,'memory','raw_pointer_unsafe',lambda n:case(f'let x={n};let p=&x as *const i32;print!("{{}}",*p);','Erreur de compilation','Créer un pointeur brut est permis en code sûr ; le déréférencer exige unsafe, même si sa validité paraît évidente.','p est un pointeur brut|La création de p n’exige pas unsafe|Le déréférencement exige un bloc unsafe','La simple création de p est interdite|Le compilateur insère automatiquement unsafe|Un pointeur brut est une référence vérifiée',mode='compile_fail'))
add(3,'enum','match_guard_fallback',lambda n:case(f'let x=Some({n});let y=match x{{Some(v) if v%2==0=>1,Some(_)=>2,None=>3}};print!("{{}}",y);',1 if n%2==0 else 2,'Une garde fausse fait poursuivre la recherche d’un bras ; elle ne rend pas le match exhaustif à elle seule.','Le deuxième bras couvre les autres Some|None est couvert séparément|La garde est testée après correspondance du motif','Une garde couvre toujours tous les Some|Le premier motif Some exclut les bras suivants même si la garde est fausse|Tous les bras sont évalués'))
add(3,'generics','impl_trait_return',lambda n:case(f'let _=make({str(n%2==0).lower()});','Erreur de compilation','impl Trait dans un retour opaque représente un unique type concret ; deux types d’itérateurs différents ne conviennent pas selon la branche.','Les deux branches ont des types concrets différents|Les deux types implémentent Iterator|Un Box<dyn Iterator<Item=i32>> serait une stratégie différente','impl Trait autorise tous les types satisfaisant le trait selon la branche|Le code est automatiquement boxé|Le choix de type est reporté à l’exécution',preamble='fn make(b:bool)->impl Iterator<Item=i32>{if b{0..3}else{std::iter::once(1)}}',mode='compile_fail'))
add(3,'ownership','mem_replace',lambda n:case(f'let mut s=String::from("old{n}");let old=std::mem::replace(&mut s,String::from("new"));print!("{{}} {{}}",old.len(),s.len());','4 3','replace déplace l’ancienne valeur vers le retour et laisse la nouvelle dans la destination, qui reste initialisée.','L’ancienne String est renvoyée|s reste initialisée|Aucun clone des String n’est nécessaire','replace laisse s désinitialisée|L’ancienne valeur est forcément détruite avant le retour|replace exige unsafe',wrong=['3 4','Erreur de compilation','4 4']))
add(3,'lifetimes','temporary_borrow',lambda n:case(f'let r=String::from("x{n}").as_str();print!("{{}}",r);','Erreur de compilation','La String temporaire de l’appel as_str est détruite à la fin de l’instruction ; r serait utilisé après sa destruction.','as_str emprunte la String|Le temporaire ne vit pas jusqu’au print ici|Une liaison propriétaire distincte corrigerait ce cas','as_str retourne une chaîne statique|L’appel clone le contenu|L’annotation de r en &str prolonge automatiquement la String',mode='compile_fail'))
add(3,'concurrency','rc_not_send',lambda n:case(f'let a=std::rc::Rc::new({n});let h=std::thread::spawn(move||*a);let _=h.join();','Erreur de compilation','Rc n’est pas Send ; ses compteurs non atomiques empêchent son transfert vers un autre thread. Arc répond à un autre contrat.','La fermeture capture le Rc|spawn exige une capture transférable|Rc n’est pas Send','move rend automatiquement tous les types Send|Rc devient Send si son contenu est i32|Le programme échoue uniquement par panic',mode='compile_fail'))
